const statusOptions = [
  {label: "Semua", value: "all"},
  {label: "Approved", value: "APPROVED"},
  {label: "Rejected", value: "REJECTED"},
  {label: "Expired", value: "EXPIRED"},
]

// --- STATE ---
const filters = reactive({
  startDate: undefined as string | undefined,
  endDate: undefined as string | undefined,
  product: "all",
  status: "all",
  page: 1,
  itemsPerPage: 10,
})

// --- COMPUTED ---
const startRecord = computed(
  () => (filters.page - 1) * filters.itemsPerPage + 1,
)

// Current Gold Price for products dropdown
const currentPriceConfig = computed(() => GoldPriceApi.getCurrent())
const {data: currentPriceRaw} = useBullionService<GoldPriceResponse>(
  currentPriceConfig,
  {
    watch: true,
  },
)

const productOptions = computed(() => {
  const items = currentPriceRaw.value?.items || []
  const opts = items
    .map((p: GoldPriceItem) => p.product)
    .filter((v: string) => v && v !== "-")
  const uniqueOpts = Array.from(new Set(opts))
  return [
    {label: "Semua", value: "all"},
    ...uniqueOpts.map((v: string) => ({label: v, value: v})),
  ]
})

// List History Gold Prices
const listConfig = computed(() =>
  GoldPriceApi.getHistory({
    page: filters.page,
    limit: filters.itemsPerPage,
    status:
      filters.status === "all"
        ? ["APPROVED", "REJECTED", "EXPIRED"]
        : filters.status,
    product: filters.product === "all" ? undefined : filters.product,
    start_date: filters.startDate || undefined,
    end_date: filters.endDate || undefined,
    nik: localStorage.getItem("accessNIK") || "P0001",
  }),
)

const {data: rawListData, execute: fetchList} =
  useBullionService<GoldPriceHistoryResponse>(listConfig, {
    watch: false,
    immediate: false,
  })

const mappedList = computed(() => {
  const raw = rawListData.value
  if (!raw) return []
  const items = raw.items || []
  return items.map((item: GoldPriceItem) => ({
    id: item.id,
    product: item.product ?? "-",
    market_price: item.market_price ?? "0",
    buy_price: item.buy_price ?? "0",
    buy_tax_rate: item.buy_tax_rate ?? "0",
    total_buy_price: item.total_buy_price ?? "0",
    sale_price: item.sale_price ?? "0",
    sale_tax_rate: item.sale_tax_rate ?? "0",
    total_sale_price: item.total_sale_price ?? "0",
    gold_price_status: item.gold_price_status ?? "-",
    effective_at: item.effective_at ?? "",
    created_at: item.created_at ?? "",
    created_by: item.created_by ?? "-",
    updated_at: item.updated_at ?? "",
    updated_by: item.updated_by ?? "-",
  }))
})

const totalItems = computed(() => {
  const raw = rawListData.value
  if (!raw) return 0
  return raw.pagination?.total_items ?? mappedList.value.length
})

const endRecord = computed(() =>
  Math.min(startRecord.value + dataTable.value.length - 1, totalItems.value),
)

const dataTable = computed(() => {
  return mappedList.value.map((item, index: number) => ({
    ...item,
    no: startRecord.value + index,
  }))
})

// --- WATCHERS ---
watch(
  () => [filters.page, filters.itemsPerPage],
  () => {
    fetchList()
  },
  {deep: true},
)

// --- HANDLERS ---
const applyFilters = () => {
  if (filters.page !== 1) {
    filters.page = 1
  } else {
    fetchList()
  }
}

const resetFilter = () => {
  filters.startDate = undefined
  filters.endDate = undefined
  filters.product = "all"
  filters.status = "all"
  applyFilters()
}

function checkStatusType(type: string) {
  if (type === "APPROVED") {
    return "primary"
  } else if (type === "REJECTED" || type === "EXPIRED") {
    return "secondary"
  } else {
    return "third"
  }
}

// --- LIFECYCLE ---
onMounted(() => {
  fetchList()
})
</script>

