const {data: currentPriceRaw, execute: fetchCurrentPrice} =
  useBullionService<GoldPriceResponse>(currentPriceConfig, {watch: true})

const currentPrices = computed<GoldPriceManagementItem[]>(() => {
  const items = currentPriceRaw.value?.items || []
  if (items.length === 0) return []
  return items.map((raw: GoldPriceItem) => ({
    priceId: raw.id?.toString() ?? "-",
    numericId: raw.id,
    product: raw.product ?? "-",
    sellPrice: parseFloat(raw.sale_price) || 0,
    buyPrice: parseFloat(raw.buy_price) || 0,
    basePrice: parseFloat(raw.market_price) || 0,
    buyTaxRate: raw.buy_tax_rate
      ? (Number(raw.buy_tax_rate) * 100).toFixed(4).replace(/\.?0+$/, "")
      : "0",
    saleTaxRate: raw.sale_tax_rate
      ? (Number(raw.sale_tax_rate) * 100).toFixed(4).replace(/\.?0+$/, "")
      : "0",
    totalBuyPrice: parseFloat(raw.total_buy_price) || 0,
    totalSalePrice: parseFloat(raw.total_sale_price) || 0,
    effectiveAt: raw.effective_at ?? "",
    createdBy: raw.created_by ?? "-",
    updatedBy: raw.updated_by ?? "-",
    goldPriceStatus: raw.gold_price_status ?? "-",
    isGenesisSynced: raw.is_genesis_synced === true,
    broadcastStatus:
      raw.is_genesis_synced === true
        ? "Synced to Genesis"
        : "Pending Genesis Sync",
  }))
})

const productOptions = computed(() => {
  return (
    rawLovProductData.value?.items.map((item) => ({
      label: item.value,
      value: item.value,
    })) || []
  )
})

const historyConfig = computed(() =>
  GoldPriceApi.getHistory({
    page: filters.page,
    limit: filters.itemsPerPage,
    nik: localStorage.getItem("accessNIK") || "P0001",
  }),
)

const {
  data: rawHistoryData,
  execute: fetchHistory,
  isLoading: isHistoryLoading,
} = useBullionService<GoldPriceHistoryResponse>(historyConfig, {
  watch: false,
  immediate: false,
})

const priceHistory = computed<GoldPriceItem[]>(() => {
  const items = rawHistoryData.value?.items || []
  return items.map((item: GoldPriceItem) => ({
    ...item,
    id: item.id,
    product: item.product ?? "-",
    market_price: item.market_price ?? "0",
    buy_price: item.buy_price ?? "0",
    buy_tax_rate: item.buy_tax_rate
      ? (Number(item.buy_tax_rate) * 100).toFixed(4).replace(/\.?0+$/, "")
      : "0",
    total_buy_price: item.total_buy_price ?? "0",
    sale_price: item.sale_price ?? "0",
    sale_tax_rate: item.sale_tax_rate
      ? (Number(item.sale_tax_rate) * 100).toFixed(4).replace(/\.?0+$/, "")
      : "0",
    total_sale_price: item.total_sale_price ?? "0",
    gold_price_status: item.gold_price_status ?? "-",
    effective_at: item.effective_at ?? "",
    created_at: item.created_at ?? "",
    created_by: item.created_by ?? "-",
    updated_at: item.updated_at ?? "",
    updated_by: item.updated_by ?? "-",
  }))
})

const dataTable = computed(() => {
  return priceHistory.value.map((item: GoldPriceItem, index: number) => ({
    ...item,
    no: startRecord.value + index,
  }))
})

const totalItems = computed<number>(() => {
  return (
    rawHistoryData.value?.pagination?.total_items ?? priceHistory.value.length
  )
})

const endRecord = computed(() =>
  Math.min(startRecord.value + dataTable.value.length - 1, totalItems.value),
)

// Executions
const {execute: executeSubmit} = useBullionService(submitConfig, {watch: false})
const {execute: executeResend} = useBullionService(resendConfig, {watch: false})

// --- WATCHERS ---
watch(
  () => [filters.page, filters.itemsPerPage],
  () => {
    fetchHistory()
  },
  {deep: true},
)

watch(
  () => [values.buyPrice, values.buyTaxRate],
  () => {
    const buyPriceNum = Number(values.buyPrice)
    const buyTaxRateNum = Number(values.buyTaxRate)
    totalBuyPrice.value = (buyPriceNum + buyPriceNum * (buyTaxRateNum / 100))
      .toFixed(2)
      .toString()
  },
)

watch(
  () => [values.sellPrice, values.saleTaxRate],
  () => {
    const sellPriceNum = Number(values.sellPrice)
    const saleTaxRateNum = Number(values.saleTaxRate)
    totalSalePrice.value = (
      sellPriceNum +
      sellPriceNum * (saleTaxRateNum / 100)
    )
      .toFixed(2)
      .toString()
  },
)

