import {AxiosRequestConfig} from "axios"
import type {
  GoldPriceApprovalPayload,
  GoldPriceCreatePayload,
  GoldPriceListParams,
} from "@/types/gold-price.type"

const BASE_URL =
  "https://gateway-digital-bullion-dev.apps.ocp-dev.pegadaian.co.id"

const DEFAULT_HEADERS = {
  "Client-ID":
    import.meta.env.VITE_CLIENT_ID || "it0M-db2c-U1wc-QZpa-Q1R8-XFCN-Oddv-DmTt",
  "Client-Module": "cms-trading",
}

export const GoldPriceApi = {
  getList: (params: GoldPriceListParams): AxiosRequestConfig => ({
    baseURL: BASE_URL,
    url: "/api/v1/bullion/inventories/gold-prices",
    method: "GET",
    params,
    headers: DEFAULT_HEADERS,
  }),

  getHistory: (params: GoldPriceListParams): AxiosRequestConfig => ({
    baseURL: BASE_URL,
    url: "/api/v1/bullion/inventories/gold-prices/history",
    method: "GET",
    params,
    paramsSerializer: (p) => {
      const searchParams = new URLSearchParams()
      for (const key in p) {
        const value = (p as Record<string, unknown>)[key]
        if (Array.isArray(value)) {
          value.forEach((v) => searchParams.append(key, String(v)))
        } else if (value !== undefined && value !== null) {
          searchParams.append(key, String(value))
        }
      }
      return searchParams.toString()
    },
    headers: DEFAULT_HEADERS,
  }),

  getCurrent: (params?: {product?: string}): AxiosRequestConfig => ({
    baseURL: BASE_URL,
    url: "/api/v1/bullion/inventories/gold-prices/current",
    method: "GET",
    params,
    headers: DEFAULT_HEADERS,
  }),

  getDetail: (id: string | number): AxiosRequestConfig => ({
    baseURL: BASE_URL,
    url: `/api/v1/bullion/inventories/gold-prices/${id}`,
    method: "GET",
    headers: DEFAULT_HEADERS,
  }),

  create: (data: GoldPriceCreatePayload): AxiosRequestConfig => ({
    baseURL: BASE_URL,
    url: "/api/v1/bullion/inventories/gold-prices",
    method: "POST",
    data,
    headers: DEFAULT_HEADERS,
  }),

  approve: (
    id: string | number,
    data: GoldPriceApprovalPayload,
  ): AxiosRequestConfig => ({
    baseURL: BASE_URL,
    url: `/api/v1/bullion/inventories/gold-prices/${id}/approval`,
    method: "PUT",
    data,
    headers: DEFAULT_HEADERS,
  }),

  resendGenesis: (
    id: string | number,
    data: {actor_id: string},
  ): AxiosRequestConfig => ({
    baseURL: BASE_URL,
    url: `/api/v1/bullion/inventories/gold-prices/${id}/resend-genesis`,
    method: "POST",
    data,
    headers: {...DEFAULT_HEADERS, "Content-Type": "application/json"},
  }),
}

